    "new_str": "pub fn to_text(config: &Config) -> String {\n    let mut result = String::new();\n\n    // Write root section\n    let root_entries = config.entries.get(&\"\".to_string()).unwrap_or(&BTreeMap::new());\n    for (key, value) in root_entries { \n        result.push_str(&format!(\"{} = {}\n\", key, value.as_str()));\n    }\n    result.push_str(&\"\\n\");\n\n    // Write named sections\n    let mut sections: Vec<&String> = config.sections.keys().cloned().collect();\n    sections.sort();\n    for section in sections {\n        if section != \"\" {\n            result.push_str(&format!(\"[{}]\n\", section));\n            if let Some(entries) = config.entries.get(section) {\n                for (key, value) in entries { \n                    result.push_str(&format!(\"{} = {}\n\", key, value.as_str()));\n                }\n            }\n            result.push_str(&\"\\n\");\n        }\n    }\n\n    result\n}",
    "old_str": null,
    "proposal_reason": "Implement the to_text function to serialize the Config to text.",
    "proposal_title": "Implement to_text function"
